/* DAYMARK: calendar-first, plain-language victory flow. */
const vpPlural=(n,one,few,many)=>{n=Math.abs(n);return n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many};
const vpRemaining=g=>Math.max(0,diff(today(),g.end));
const vpMonthCount=(g,ym)=>Object.keys(g.checks).filter(d=>d.startsWith(ym)).length;
const vpStreak=g=>{let d=today(),n=0;if(!g.checks[d])d=offset(d,-1);while(g.checks[d]&&d>=g.start){n++;d=offset(d,-1);}return n;};

victoryCalendar=function(g,ym,weekOnly=false){const [y,m]=ym.split('-').map(Number),first=ym+'-01',length=new Date(Date.UTC(y,m,0)).getUTCDate(),offsetDays=(dt(first).getUTCDay()+6)%7;let html='<div class="calendar-mini victory-grid vp-grid" role="group" aria-label="Календар '+monthTitle(ym)+'">'+['Пн','Вт','Ср','Чт','Пт','Сб','Нд'].map(n=>'<span class="week-label">'+n+'</span>').join('');for(let i=0;i<offsetDays;i++)html+='<span class="day empty"></span>';for(let i=1;i<=length;i++){const d=ym+'-'+String(i).padStart(2,'0'),c=g.checks[d],valid=d>=g.start&&d<=g.end&&d<=today();html+='<button class="day '+(c?'completed ':'')+(c==='minimum'?'minimum ':'')+(d===today()?'today ':'')+(!valid?'future ':'')+(d===selectedDate?'active-date ':'')+(d===justMarkedDate?'just-won ':'')+'" data-action="calendar-day" data-date="'+d+'" '+(!valid?'disabled':'')+' aria-label="'+fdate(d,true)+(c?' — день закреслено':' — позначити день')+'"><span class="day-number">'+i+'</span>'+(c?'<span class="vp-slash" aria-hidden="true"></span>':'')+'</button>';}return html+'</div>';};

rewardCalendar=function(){const g=goal(),c=g.checks[selectedDate],marked=completed(g),remaining=vpRemaining(g),ym=monthView,monthN=vpMonthCount(g,ym),valid=selectedDate>=g.start&&selectedDate<=g.end&&selectedDate<=today();return '<section class="reward-calendar vp-calendar"><div class="vp-calendar-top"><span>МІЙ КАЛЕНДАР</span><button data-view="journey">Весь шлях ↗</button></div><h2>'+esc(g.title)+'</h2><p class="vp-calendar-sub">Кожен закреслений день — ще один день, коли ти зробив крок до цілі.</p><div class="vp-counts"><div><strong>'+marked+'</strong><span>'+vpPlural(marked,'день','дні','днів')+' закреслено</span></div><div><strong>'+remaining+'</strong><span>'+vpPlural(remaining,'день','дні','днів')+' до твоєї дати</span></div></div><div class="vp-month-head"><button data-action="month-prev" aria-label="Попередній місяць">‹</button><div><strong>'+monthTitle(ym)+'</strong><small>'+monthN+' '+vpPlural(monthN,'позначка','позначки','позначок')+' цього місяця</small></div><button data-action="month-next" aria-label="Наступний місяць">›</button></div>'+victoryCalendar(g,ym)+'<div class="vp-calendar-legend"><span><i></i>Закреслено</span><span><i></i>Сьогодні</span></div><button class="victory-button vp-mark '+(c?'is-done':'')+'" data-action="'+(c?'mark':'quick-mark')+'" '+(!valid?'disabled':'')+'><span class="victory-icon">'+(c?'✓':'╱')+'</span><span><b>'+(c?'День '+Number(selectedDate.slice(-2))+' закреслено':'Закреслити '+Number(selectedDate.slice(-2))+' '+monthTitle(selectedDate.slice(0,7)).split(' ')[0])+'</b><small>'+(c?'Натисни, щоб змінити або прибрати позначку':'Один дотик — і день у твоєму календарі')+'</small></span><i>↗</i></button></section>';};

journeyView=function(){const g=goal(),n=completed(g),totalDays=total(g),remaining=vpRemaining(g),streak=vpStreak(g);let monthsHtml='',cursor=g.start.slice(0,7),end=g.end.slice(0,7),limit=0;while(cursor<=end&&limit++<25){const count=vpMonthCount(g,cursor);monthsHtml+='<section class="vp-journey-month"><div class="vp-journey-month-title"><h3>'+monthTitle(cursor)+'</h3><span>'+count+' '+vpPlural(count,'день','дні','днів')+'</span></div>'+victoryCalendar(g,cursor)+'</section>';cursor=months(cursor+'-01',1).slice(0,7);}return pageTop('Мій шлях','МІЙ КАЛЕНДАР / '+esc(g.title),'<button class="btn ghost small-btn" data-view="goals">Мої цілі ↗</button>')+'<section class="vp-journey-hero"><span>ЦІЛЬ ДО '+fdate(g.end,true).toUpperCase()+'</span><h2>'+esc(g.title)+'</h2><p>'+fdate(g.start,true)+' — '+fdate(g.end,true)+'</p><div class="vp-journey-stats"><div><b>'+n+'</b><small>днів закреслено</small></div><div><b>'+streak+'</b><small>поспіль зараз</small></div><div><b>'+remaining+'</b><small>днів до дати</small></div></div><div class="vp-track"><i style="width:'+Math.min(100,n/Math.max(1,totalDays)*100)+'%"></i></div><p class="vp-track-label">'+n+' із '+totalDays+' днів у календарі</p></section><div class="vp-journey-explain"><span>╱</span><p><b>Як це працює?</b> Натисни на дату, щоб позначити день. Закреслені дні видно одразу; пропущені не стирають твій прогрес.</p></div><div class="vp-journey-months">'+monthsHtml+'</div><button class="vp-journey-coach" data-view="coach">Подивитися аналіз мого дня ↗</button>';};

const vpOriginalRows=supportRows;
supportRows=function(g,compact=false){return g.habits.map(id=>{const x=supportStatus(g,id),group=x.def.group,emoji=SUPPORT_SYMBOLS[id]||'✓',status=x.done?'Зроблено':x.planned?'Ще не внесено':'День відпочинку',source=x.automatic?'Дані зі щоденника':'Позначити вручну';return '<button class="vp-step '+group+(x.done?' done':'')+'" data-action="support-open" data-id="'+id+'" aria-label="'+esc(x.label)+'. '+status+'. Відкрити"><span class="vp-step-icon" aria-hidden="true">'+emoji+'</span><span class="vp-step-main"><span class="vp-step-title">'+esc(x.label)+'</span><span class="vp-step-detail">'+(x.done?esc(supportReadout(x)):source)+'</span></span><span class="vp-step-status">'+(x.done?'✓':'↗')+'</span></button>';}).join('');};

markModal=function(minimum=false,d=selectedDate){const g=goal();if(d<g.start||d>g.end||d>today())return;modalData={date:d,minimum};const c=g.checks[d],day=fdate(d,true);if(c){openModal('КАЛЕНДАР / '+day,'<div class="vp-mark-modal"><span class="vp-mark-modal-icon">✓</span><h2>'+day+' закреслено</h2><p>Цей день уже є в календарі цілі «'+esc(g.title)+'».</p><button class="btn ghost full" data-action="unmark">Прибрати позначку з цього дня</button><button class="btn blue full" data-action="close-modal">Залишити як є</button></div>');return;}openModal('КАЛЕНДАР / '+day,'<div class="vp-mark-modal"><span class="vp-mark-modal-icon">╱</span><h2>Закреслити '+day+'?</h2><p>День стане яскравою позначкою в календарі цілі «'+esc(g.title)+'».</p><button class="btn blue full" data-action="confirm-mark">Так, закреслити день</button><button class="btn ghost full" data-action="close-modal">Не зараз</button></div>');};
actions['close-modal']=()=>closeModal();
actions['calendar-day']=button=>{selectedDate=button.dataset.date;render();markModal(false,selectedDate);};
const vpRewardBase=rewardCalendar;
rewardCalendar=function(){return vpRewardBase().replace('Закреслити '+Number(selectedDate.slice(-2))+' '+monthTitle(selectedDate.slice(0,7)).split(' ')[0],'Закреслити '+fdate(selectedDate));};
const vpShowVictory=showVictory;
showVictory=function(mode='full'){vpShowVictory(mode);const box=$('celebration'),g=goal(),n=completed(g),heading=box.querySelector('h2'),p=box.querySelector('p');if(heading)heading.textContent='День '+Number(selectedDate.slice(-2))+' закреслено!';if(p)p.textContent=n+' '+vpPlural(n,'день','дні','днів')+' у твоєму календарі · ще '+vpRemaining(g)+' до дати цілі';};
